window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dd1766c5e8b87d99"]={"versions": [{"id": "FIG-dd1766c5e8b87d99", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Definition) des BSW-Moduls <code>CanNm</code>. Das Diagramm beschreibt die hierarchische Top-Level-Containerstruktur der Moduldefinition im Kontext des AUTOSAR Classic Platform Konfigurationsmetamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert drei Hauptelemente und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CanNm :EcucModuleDef</code>: Repräsentiert die Moduldefinition mit den Kardinalitätsattributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanNmGlobalConfig :EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer, der über eine Komposition mit der Rolle <code>+container</code> an <code>CanNm</code> angebunden ist. Enthält das Metamodell-Attribut <code>multipleConfigurationContainer = true</code>.</li>\n<li><code>CanNmChannelConfig :EcucParamConfContainerDef</code>: Kanalspezifischer Konfigurationscontainer, der über eine Komposition mit der Rolle <code>+subContainer</code> an <code>CanNmGlobalConfig</code> gebunden ist. Enthält die Attribute <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell beinhaltet das Diagramm keine Laufzeitsequenzen. Es definiert die statische Schachtelungstiefe und Instanziierungsregeln bei der Konfiguration: Ein <code>CanNm</code>-Modul aggregiert genau die globale Containerdefinition <code>CanNmGlobalConfig</code>, welche wiederum mindestens einen bis beliebig viele kanalspezifische Container <code>CanNmChannelConfig</code> aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-Konfigurationsstruktur für CAN NM.</p>\n<ul class=\"fig-list\">\n<li>Entwickler und Konfigurationswerkzeuge müssen sicherstellen, dass <code>CanNmGlobalConfig</code> als Multi-Configuration-Container (<code>multipleConfigurationContainer = true</code>) fungiert.</li>\n<li><code>CanNmChannelConfig</code> muss pro CAN-Kanal mindestens einmal vorhanden sein (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>).</li>\n<li>Die Schachtelung erfolgt zwingend über die Kompositionsbeziehungen <code>+container</code> und <code>+subContainer</code>.</li>\n</ul>"}, {"id": "FIG-617408cac7d618a0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Definition) des BSW-Moduls <code>CanNm</code>. Das Diagramm beschreibt die hierarchische Top-Level-Containerstruktur der Moduldefinition im Kontext des AUTOSAR Classic Platform Konfigurationsmetamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert drei Hauptelemente und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CanNm :EcucModuleDef</code>: Moduldefinition mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanNmGlobalConfig :EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+container</code> an <code>CanNm</code>, mit dem Attribut <code>multipleConfigurationContainer = true</code>.</li>\n<li><code>CanNmChannelConfig :EcucParamConfContainerDef</code>: Kanalspezifischer Untercontainer, angebunden über die Kompositionsrolle <code>+subContainer</code> an <code>CanNmGlobalConfig</code>, mit den Attributen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code> sowie <code>postBuildChangeable = false</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell beinhaltet das Diagramm keine Laufzeitsequenzen. Es definiert die statische Schachtelungstiefe und Instanziierungsregeln bei der Konfiguration: Ein <code>CanNm</code>-Modul aggregiert genau die globale Containerdefinition <code>CanNmGlobalConfig</code>, welche wiederum mindestens einen bis beliebig viele kanalspezifische Container <code>CanNmChannelConfig</code> aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-Konfigurationsstruktur für CAN NM.</p>\n<ul class=\"fig-list\">\n<li>Entwickler und Generatoren müssen berücksichtigen, dass <code>CanNmGlobalConfig</code> als <code>multipleConfigurationContainer = true</code> ausgelegt ist.</li>\n<li><code>CanNmChannelConfig</code> besitzt die Multiplizität 1..* und darf zur Post-Build-Zeit nicht geändert werden (<code>postBuildChangeable = false</code>).</li>\n<li>Die Schachtelungshierarchie verlangt die Einbettung der Kanalcontainer unterhalb des globalen Konfigurationscontainers.</li>\n</ul>"}, {"id": "FIG-87165dc37cb79165", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Definition) des BSW-Moduls <code>CanNm</code>. Das Diagramm beschreibt die hierarchische Top-Level-Containerstruktur der Moduldefinition im Kontext des AUTOSAR Classic Platform Konfigurationsmetamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert drei Hauptelemente und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CanNm :EcucModuleDef</code>: Moduldefinition mit den Attributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanNmGlobalConfig :EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer ohne zusätzliche Container-Flags, angebunden über die Kompositionsrolle <code>+container</code> an <code>CanNm</code>.</li>\n<li><code>CanNmChannelConfig :EcucParamConfContainerDef</code>: Kanalspezifischer Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+subContainer</code> an <code>CanNmGlobalConfig</code>, mit den Attributen <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell beinhaltet das Diagramm keine Laufzeitsequenzen. Es definiert die statische Schachtelungstiefe und Instanziierungsregeln bei der Konfiguration: Ein <code>CanNm</code>-Modul aggregiert genau die globale Containerdefinition <code>CanNmGlobalConfig</code>, welche wiederum mindestens einen bis beliebig viele kanalspezifische Container <code>CanNmChannelConfig</code> aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-Konfigurationsstruktur für CAN NM.</p>\n<ul class=\"fig-list\">\n<li><code>CanNmGlobalConfig</code> besitzt kein explizites <code>multipleConfigurationContainer</code>-Flag mehr im Schaubild.</li>\n<li><code>CanNmChannelConfig</code> ist mit der Multiplizität 1..* definiert; das Attribut <code>postBuildChangeable</code> wird nicht mehr auf Containerebene aufgeführt.</li>\n<li>Konfigurationswerkzeuge validieren die Containereinbettung <code>CanNm</code> -> <code>CanNmGlobalConfig</code> (<code>+container</code>) -> <code>CanNmChannelConfig</code> (<code>+subContainer</code>).</li>\n</ul>"}, {"id": "FIG-7aa06024ffcee613", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Definition) des BSW-Moduls <code>CanNm</code>. Das Diagramm beschreibt die hierarchische Top-Level-Containerstruktur der Moduldefinition im Kontext des AUTOSAR Classic Platform Konfigurationsmetamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert drei Hauptelemente und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CanNm :EcucModuleDef</code>: Moduldefinition mit den Attributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanNmGlobalConfig :EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer ohne zusätzliche Container-Flags, angebunden über die Kompositionsrolle <code>+container</code> an <code>CanNm</code>.</li>\n<li><code>CanNmChannelConfig :EcucParamConfContainerDef</code>: Kanalspezifischer Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+subContainer</code> an <code>CanNmGlobalConfig</code>, mit den Attributen <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell beinhaltet das Diagramm keine Laufzeitsequenzen. Es definiert die statische Schachtelungstiefe und Instanziierungsregeln bei der Konfiguration: Ein <code>CanNm</code>-Modul aggregiert genau die globale Containerdefinition <code>CanNmGlobalConfig</code>, welche wiederum mindestens einen bis beliebig viele kanalspezifische Container <code>CanNmChannelConfig</code> aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-Konfigurationsstruktur für CAN NM.</p>\n<ul class=\"fig-list\">\n<li><code>CanNmGlobalConfig</code> besitzt kein explizites <code>multipleConfigurationContainer</code>-Flag mehr im Schaubild.</li>\n<li><code>CanNmChannelConfig</code> ist mit der Multiplizität 1..* definiert; das Attribut <code>postBuildChangeable</code> wird nicht mehr auf Containerebene aufgeführt.</li>\n<li>Konfigurationswerkzeuge validieren die Containereinbettung <code>CanNm</code> -> <code>CanNmGlobalConfig</code> (<code>+container</code>) -> <code>CanNmChannelConfig</code> (<code>+subContainer</code>).</li>\n</ul>"}, {"id": "FIG-d3c8bb0ad64c1bec", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Definition) des BSW-Moduls <code>CanNm</code>. Das Diagramm beschreibt die hierarchische Top-Level-Containerstruktur der Moduldefinition im Kontext des AUTOSAR Classic Platform Konfigurationsmetamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert drei Hauptelemente und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CanNm: EcucModuleDef</code>: Moduldefinition mit den Attributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanNmGlobalConfig: EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+container</code> an <code>CanNm</code>.</li>\n<li><code>CanNmChannelConfig: EcucParamConfContainerDef</code>: Kanalspezifischer Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+subContainer</code> an <code>CanNmGlobalConfig</code>, mit den Attributen <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell beinhaltet das Diagramm keine Laufzeitsequenzen. Es definiert die statische Schachtelungstiefe und Instanziierungsregeln bei der Konfiguration: Ein <code>CanNm</code>-Modul aggregiert genau die globale Containerdefinition <code>CanNmGlobalConfig</code>, welche wiederum mindestens einen bis beliebig viele kanalspezifische Container <code>CanNmChannelConfig</code> aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-Konfigurationsstruktur für CAN NM.</p>\n<ul class=\"fig-list\">\n<li><code>CanNmGlobalConfig</code> besitzt kein explizites <code>multipleConfigurationContainer</code>-Flag mehr im Schaubild.</li>\n<li><code>CanNmChannelConfig</code> ist mit der Multiplizität 1..* definiert; das Attribut <code>postBuildChangeable</code> wird nicht mehr auf Containerebene aufgeführt.</li>\n<li>Konfigurationswerkzeuge validieren die Containereinbettung <code>CanNm</code> -> <code>CanNmGlobalConfig</code> (<code>+container</code>) -> <code>CanNmChannelConfig</code> (<code>+subContainer</code>).</li>\n</ul>"}, {"id": "FIG-6b2e5eada6cbf992", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt für die AUTOSAR-ECU-Konfigurationsparameterdefinition (ECUC Parameter Definition) des BSW-Moduls <code>CanNm</code>. Das Diagramm beschreibt die hierarchische Top-Level-Containerstruktur der Moduldefinition im Kontext des AUTOSAR Classic Platform Konfigurationsmetamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell definiert drei Hauptelemente und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CanNm: EcucModuleDef</code>: Moduldefinition mit den Attributen <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = 1</code>.</li>\n<li><code>CanNmGlobalConfig: EcucParamConfContainerDef</code>: Globaler Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+container</code> an <code>CanNm</code>.</li>\n<li><code>CanNmChannelConfig: EcucParamConfContainerDef</code>: Kanalspezifischer Konfigurationscontainer, angebunden über die Kompositionsrolle <code>+subContainer</code> an <code>CanNmGlobalConfig</code>, mit den Attributen <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = *</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell beinhaltet das Diagramm keine Laufzeitsequenzen. Es definiert die statische Schachtelungstiefe und Instanziierungsregeln bei der Konfiguration: Ein <code>CanNm</code>-Modul aggregiert genau die globale Containerdefinition <code>CanNmGlobalConfig</code>, welche wiederum mindestens einen bis beliebig viele kanalspezifische Container <code>CanNmChannelConfig</code> aggregiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-Konfigurationsstruktur für CAN NM.</p>\n<ul class=\"fig-list\">\n<li><code>CanNmGlobalConfig</code> besitzt kein explizites <code>multipleConfigurationContainer</code>-Flag mehr im Schaubild.</li>\n<li><code>CanNmChannelConfig</code> ist mit der Multiplizität 1..* definiert; das Attribut <code>postBuildChangeable</code> wird nicht mehr auf Containerebene aufgeführt.</li>\n<li>Konfigurationswerkzeuge validieren die Containereinbettung <code>CanNm</code> -> <code>CanNmGlobalConfig</code> (<code>+container</code>) -> <code>CanNmChannelConfig</code> (<code>+subContainer</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-dd1766c5e8b87d99", "to": "FIG-617408cac7d618a0", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <code>CanNmChannelConfig</code>: Attribut <code>postBuildChangeable = false</code> hinzugefügt.</li>\n<li>Layout der Assoziationsrollen <code>+container</code> und <code>+subContainer</code> typografisch bereinigt.</li>\n</ul>"}, {"from": "FIG-617408cac7d618a0", "to": "FIG-87165dc37cb79165", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <code>CanNmGlobalConfig</code>: Attribut <code>multipleConfigurationContainer = true</code> entfernt.</li>\n<li>In <code>CanNmChannelConfig</code>: Attribut <code>postBuildChangeable = false</code> entfernt.</li>\n</ul>"}, {"from": "FIG-87165dc37cb79165", "to": "FIG-7aa06024ffcee613", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7aa06024ffcee613", "to": "FIG-d3c8bb0ad64c1bec", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>In den Headern von <code>CanNm</code>, <code>CanNmGlobalConfig</code> und <code>CanNmChannelConfig</code>: Leerzeichen vor dem Doppelpunkt entfernt (<code> :</code> zu <code>:</code>).</li>\n</ul>"}, {"from": "FIG-d3c8bb0ad64c1bec", "to": "FIG-6b2e5eada6cbf992", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
